def solve(frame):
    cm, pl, gl = get_map(frame)
    R=[5,7,9,11,13,15]
    def cell(r,c): return cm.get((r,c),'B')
    def nbrs(n):
        r,c=n; out=[]
        for act,dr,dc in (('RIGHT',0,2),('LEFT',0,-2),('DOWN',2,0),('UP',-2,0)):
            nr,nc=r+dr,c+dc
            if nr not in R or nc not in R: continue
            if cell(nr,nc)=='B': continue
            d = cell(r,(c+nc)//2) if dc else cell((r+nr)//2,c)
            if d=='g': out.append(((nr,nc),act))
        return out
    q=collections.deque([(pl,[])]); seen={pl}
    while q:
        n,p=q.popleft()
        if n==gl: return p, pl, gl, len(seen)
        for m,a in nbrs(n):
            if m not in seen:
                seen.add(m); q.append((m,p+[a]))
    return None,pl,gl,len(seen)

